<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_permission('inventory.view');
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_permission('inventory.manage');verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='asset'){$tag=trim((string)($_POST['asset_tag']??''));$name=trim((string)($_POST['name']??''));$category=trim((string)($_POST['category']??''));$location=trim((string)($_POST['location']??''));if($tag===''||strlen($tag)>80||$name===''||strlen($name)>160||$category===''||strlen($category)>100||strlen($location)>160){set_flash('danger','Enter an asset tag, name, category, and optional location.');redirect('/hospital%20management/inventory/equipment.php');}$q=$pdo->prepare("INSERT INTO equipment_assets(asset_tag,name,category,location) VALUES(:tag,:name,:category,:location)");$q->execute(['tag'=>$tag,'name'=>$name,'category'=>$category,'location'=>$location?:null]);$id=(string)$pdo->lastInsertId();record_audit('create','equipment_asset',$id,'Equipment asset registered');set_flash('success','Equipment registered.');}
 elseif($action==='schedule'){$asset=filter_var($_POST['asset_id']??'',FILTER_VALIDATE_INT);$date=trim((string)($_POST['scheduled_on']??''));$type=trim((string)($_POST['maintenance_type']??''));$details=trim((string)($_POST['details']??''));$parsed=DateTime::createFromFormat('!Y-m-d',$date);if(!$asset||!$parsed||$parsed->format('Y-m-d')!==$date||$type===''||strlen($type)>120||strlen($details)>1000){set_flash('danger','Choose equipment, a valid date, and maintenance type.');redirect('/hospital%20management/inventory/equipment.php');}$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT id FROM equipment_assets WHERE id=:id AND status<>'retired' FOR UPDATE");$q->execute(['id'=>$asset]);if(!$q->fetch())throw new RuntimeException('Equipment asset is unavailable.');$pdo->prepare('INSERT INTO equipment_maintenance(asset_id,scheduled_on,maintenance_type,details,recorded_by) VALUES(:asset,:date,:type,:details,:user)')->execute(['asset'=>$asset,'date'=>$date,'type'=>$type,'details'=>$details?:null,'user'=>current_user()['id']]);$id=(string)$pdo->lastInsertId();$pdo->prepare("UPDATE equipment_assets SET status='maintenance' WHERE id=:id")->execute(['id'=>$asset]);record_audit('schedule','equipment_maintenance',$id,'Equipment maintenance scheduled');$pdo->commit();set_flash('success','Maintenance scheduled.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Maintenance could not be scheduled.');}}
 elseif($action==='complete'){$id=filter_var($_POST['maintenance_id']??'',FILTER_VALIDATE_INT);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT asset_id,status FROM equipment_maintenance WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$maintenance=$q->fetch();if(!$maintenance||$maintenance['status']!=='scheduled')throw new RuntimeException('Maintenance record is no longer open.');$pdo->prepare("UPDATE equipment_maintenance SET status='completed',completed_at=NOW() WHERE id=:id")->execute(['id'=>$id]);$check=$pdo->prepare("SELECT COUNT(*) FROM equipment_maintenance WHERE asset_id=:asset AND status='scheduled'");$check->execute(['asset'=>$maintenance['asset_id']]);if((int)$check->fetchColumn()===0)$pdo->prepare("UPDATE equipment_assets SET status='available' WHERE id=:id AND status='maintenance'")->execute(['id'=>$maintenance['asset_id']]);record_audit('complete','equipment_maintenance',(string)$id,'Maintenance completed');$pdo->commit();set_flash('success','Maintenance marked complete.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Maintenance status could not be changed.');}}
 else{http_response_code(400);exit('Unknown equipment action.');}redirect('/hospital%20management/inventory/equipment.php');
}
$assets=$pdo->query('SELECT id,asset_tag,name,category,location,status FROM equipment_assets ORDER BY category,name')->fetchAll();$maintenance=$pdo->query('SELECT m.id,m.scheduled_on,m.maintenance_type,m.details,m.status,m.completed_at,a.asset_tag,a.name,u.full_name AS recorded_by FROM equipment_maintenance m JOIN equipment_assets a ON a.id=m.asset_id JOIN users u ON u.id=m.recorded_by ORDER BY CASE WHEN m.status=\'scheduled\' THEN 0 ELSE 1 END,m.scheduled_on DESC LIMIT 300')->fetchAll();
$pageTitle='Equipment and maintenance';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Equipment and maintenance</h2><p>Maintain the hospital equipment register and schedule service work.</p></div><a class="btn btn-outline-secondary" href="/hospital%20management/inventory/index.php">Inventory</a></div>
<?php if(has_permission('inventory.manage')):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Register equipment</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="asset"><div class="col-md-3"><label class="form-label">Asset tag</label><input class="form-control" name="asset_tag" maxlength="80" required></div><div class="col-md-3"><label class="form-label">Equipment</label><input class="form-control" name="name" maxlength="160" required></div><div class="col-md-2"><label class="form-label">Category</label><input class="form-control" name="category" maxlength="100" required></div><div class="col-md-2"><label class="form-label">Location</label><input class="form-control" name="location" maxlength="160"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary">Add equipment</button></div></form></section><section class="content-card"><div class="card-heading"><h3>Schedule maintenance</h3></div><form method="post" class="row g-3 p-3"><?=csrf_field()?><input type="hidden" name="action" value="schedule"><div class="col-md-4"><label class="form-label">Equipment asset</label><select class="form-select" name="asset_id" required><option value="">Select equipment</option><?php foreach($assets as $a):if($a['status']!=='retired'):?><option value="<?=(int)$a['id']?>"><?=e($a['asset_tag'].' · '.$a['name'])?></option><?php endif;endforeach;?></select></div><div class="col-md-2"><label class="form-label">Scheduled date</label><input class="form-control" type="date" name="scheduled_on" required></div><div class="col-md-3"><label class="form-label">Maintenance type</label><input class="form-control" name="maintenance_type" maxlength="120" placeholder="Inspection, repair, calibration" required></div><div class="col-md-3"><label class="form-label">Details</label><input class="form-control" name="details" maxlength="1000"></div><div class="col-12"><button class="btn btn-primary">Schedule maintenance</button></div></form></section><?php endif;?>
<section class="content-card"><div class="card-heading"><h3>Equipment register</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Asset tag</th><th>Equipment</th><th>Category</th><th>Location</th><th>Status</th></tr></thead><tbody><?php if(!$assets):?><tr><td colspan="5" class="empty-state">No equipment registered.</td></tr><?php else:foreach($assets as $a):?><tr><td><?=e($a['asset_tag'])?></td><td><?=e($a['name'])?></td><td><?=e($a['category'])?></td><td><?=e($a['location']?:'—')?></td><td><?=e(ucfirst($a['status']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="content-card"><div class="card-heading"><h3>Maintenance schedule and history</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Asset</th><th>Work</th><th>Details</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$maintenance):?><tr><td colspan="6" class="empty-state">No maintenance scheduled.</td></tr><?php else:foreach($maintenance as $m):?><tr><td><?=e(date('M j, Y',strtotime($m['scheduled_on'])))?></td><td><?=e($m['asset_tag'].' · '.$m['name'])?></td><td><?=e($m['maintenance_type'])?></td><td><?=e($m['details']?:'—')?></td><td><?=e(ucfirst($m['status']))?></td><td><?php if(has_permission('inventory.manage')&&$m['status']==='scheduled'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="complete"><input type="hidden" name="maintenance_id" value="<?=(int)$m['id']?>"><button class="btn btn-sm btn-outline-secondary">Mark complete</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
